"""gitignore-style pattern matching. See task.md."""

from __future__ import annotations


class PatternError(ValueError):
    """Raised for a malformed character class or a dangling escape."""


def is_ignored(patterns: list[str], path: str, is_dir: bool) -> bool:
    """Return True when `path` is ignored by `patterns`."""
    # Compile all patterns first (to catch errors early)
    compiled_patterns = []
    for pattern_line in patterns:
        compiled = parse_and_compile_pattern(pattern_line)
        if compiled is not None:
            compiled_patterns.append(compiled)

    # Walk patterns in order and find the last matching pattern
    last_match = None
    for compiled in compiled_patterns:
        if matches_pattern(compiled, path, is_dir):
            last_match = compiled

    if last_match is None:
        return False  # Nothing matched, not ignored

    # If the last match is a negation, the path is NOT ignored
    return not last_match['is_negation']


def parse_and_compile_pattern(line: str) -> dict | None:
    """Parse and compile a single pattern line. Returns None if line is blank/comment."""
    # Step 1: Remove trailing spaces (but keep escaped ones)
    line = remove_trailing_spaces(line)

    # Step 2: If blank, ignore
    if not line:
        return None

    # Step 3: If starts with '#', it's a comment
    if line.startswith('#'):
        return None

    # Step 4: Check for negation
    is_negation = False
    if line.startswith('!'):
        is_negation = True
        line = line[1:]

    # Step 5: Check for directory-only
    is_directory_only = False
    if line.endswith('/'):
        is_directory_only = True
        line = line[:-1]

    # Step 6: If nothing left, ignore
    if not line:
        return None

    # Now check if it's anchored and split into segments
    is_anchored = '/' in line
    if is_anchored and line.startswith('/'):
        line = line[1:]

    # Split into segments and compile each
    segments = line.split('/')
    compiled_segments = [compile_segment(seg) for seg in segments]

    return {
        'is_negation': is_negation,
        'is_directory_only': is_directory_only,
        'is_anchored': is_anchored,
        'segments': compiled_segments,
    }


def remove_trailing_spaces(line: str) -> str:
    """Remove trailing spaces, but keep escaped ones."""
    if not line:
        return line

    # Find the start of trailing spaces
    i = len(line) - 1
    while i >= 0 and line[i] == ' ':
        i -= 1

    # If no trailing spaces, return as is
    if i == len(line) - 1:
        return line

    # Count consecutive backslashes before the trailing spaces
    backslash_count = 0
    j = i
    while j >= 0 and line[j] == '\\':
        backslash_count += 1
        j -= 1

    # If odd number of backslashes, keep one space
    if backslash_count % 2 == 1:
        return line[:i + 2]
    else:
        # Remove all trailing spaces
        return line[:i + 1]


def compile_segment(segment: str) -> dict:
    """Compile a single path segment into a list of atoms."""
    if segment == '**':
        return {'type': 'doublestar'}

    atoms = []
    i = 0
    while i < len(segment):
        if segment[i] == '*':
            atoms.append({'type': 'star'})
            i += 1
        elif segment[i] == '?':
            atoms.append({'type': 'question'})
            i += 1
        elif segment[i] == '[':
            char_class = parse_char_class(segment, i)
            atoms.append({'type': 'class', 'class': char_class['atoms']})
            i = char_class['next_i']
        elif segment[i] == '\\':
            if i + 1 >= len(segment):
                raise PatternError("Backslash with nothing after it in segment")
            atoms.append({'type': 'literal', 'char': segment[i + 1]})
            i += 2
        else:
            atoms.append({'type': 'literal', 'char': segment[i]})
            i += 1

    return {'type': 'glob', 'atoms': atoms}


def parse_char_class(segment: str, start_i: int) -> dict:
    """Parse a character class [...] starting at start_i."""
    i = start_i + 1  # Skip '['

    # Check for negation
    negated = False
    if i < len(segment) and segment[i] == '!':
        negated = True
        i += 1

    members = []

    # Special case: ] right after [ or [!
    if i < len(segment) and segment[i] == ']':
        members.append({'type': 'literal', 'char': ']'})
        i += 1

    # Parse the rest of the class
    while i < len(segment):
        if segment[i] == ']':
            # End of class
            return {'atoms': {'negated': negated, 'members': members}, 'next_i': i + 1}

        # Parse one member (which might be a range)
        if segment[i] == '\\':
            # Escape
            if i + 1 >= len(segment):
                raise PatternError("Backslash with nothing after it in character class")
            start_char = segment[i + 1]
            i += 2
        else:
            start_char = segment[i]
            i += 1

        # Check for range
        if i < len(segment) and segment[i] == '-' and i + 1 < len(segment) and segment[i + 1] != ']':
            i += 1  # Skip '-'

            if segment[i] == '\\':
                if i + 1 >= len(segment):
                    raise PatternError("Backslash with nothing after it in character class")
                end_char = segment[i + 1]
                i += 2
            else:
                end_char = segment[i]
                i += 1

            if ord(end_char) < ord(start_char):
                raise PatternError(f"Invalid range [{start_char}-{end_char}]")
            members.append({'type': 'range', 'start': start_char, 'end': end_char})
        else:
            members.append({'type': 'literal', 'char': start_char})

    # No closing ]
    raise PatternError("Unterminated character class")


def matches_pattern(pattern: dict, path: str, is_dir: bool) -> bool:
    """Check if a path matches a compiled pattern."""
    # Check directory-only constraint
    if pattern['is_directory_only'] and not is_dir:
        return False

    path_segments = path.split('/')
    pattern_segments = pattern['segments']

    if pattern['is_anchored']:
        # Root-anchored: must match from the root
        return match_segments(pattern_segments, path_segments)
    else:
        # Not anchored: match against the basename at any depth
        # Try matching the pattern against all suffixes of the path
        for i in range(len(path_segments)):
            if match_segments(pattern_segments, path_segments[i:]):
                return True
        return False


def match_segments(pattern_segments: list, path_segments: list) -> bool:
    """Match pattern segments against path segments."""
    pi = 0  # Pattern segment index
    si = 0  # Path segment index

    while pi < len(pattern_segments):
        pattern_seg = pattern_segments[pi]

        if pattern_seg['type'] == 'doublestar':
            # Handle ** (zero or more segments)
            # Special case: if it's the last segment, it means one or more
            is_last_segment = (pi == len(pattern_segments) - 1)

            if is_last_segment:
                # Trailing **: must have at least one remaining segment
                return si < len(path_segments)
            else:
                # Leading or middle **: try matching rest of pattern with zero or more segments consumed
                for skip in range(len(path_segments) - si + 1):
                    if match_segments(pattern_segments[pi + 1:], path_segments[si + skip:]):
                        return True
                return False
        else:
            # Regular glob segment
            if si >= len(path_segments):
                return False

            if not match_glob_segment(pattern_seg, path_segments[si]):
                return False

            si += 1
            pi += 1

    # All pattern segments matched
    return si == len(path_segments)


def match_glob_segment(seg_pattern: dict, path_seg: str) -> bool:
    """Match a glob segment pattern against a path segment."""
    atoms = seg_pattern['atoms']
    memo = {}

    def match_atoms(atom_idx: int, seg_idx: int) -> bool:
        if (atom_idx, seg_idx) in memo:
            return memo[(atom_idx, seg_idx)]

        # Base cases
        if atom_idx == len(atoms):
            result = seg_idx == len(path_seg)
        elif seg_idx > len(path_seg):
            result = False
        else:
            atom = atoms[atom_idx]

            if atom['type'] == 'star':
                # * matches zero or more characters
                result = False
                # Try matching zero characters first
                if match_atoms(atom_idx + 1, seg_idx):
                    result = True
                else:
                    # Try matching one or more characters
                    for i in range(seg_idx, len(path_seg)):
                        if match_atoms(atom_idx + 1, i + 1):
                            result = True
                            break
            elif atom['type'] == 'question':
                # ? matches exactly one character
                if seg_idx < len(path_seg):
                    result = match_atoms(atom_idx + 1, seg_idx + 1)
                else:
                    result = False
            elif atom['type'] == 'literal':
                # Literal character
                if seg_idx < len(path_seg) and path_seg[seg_idx] == atom['char']:
                    result = match_atoms(atom_idx + 1, seg_idx + 1)
                else:
                    result = False
            elif atom['type'] == 'class':
                # Character class
                if seg_idx < len(path_seg) and match_char_in_class(atom['class'], path_seg[seg_idx]):
                    result = match_atoms(atom_idx + 1, seg_idx + 1)
                else:
                    result = False

        memo[(atom_idx, seg_idx)] = result
        return result

    return match_atoms(0, 0)


def match_char_in_class(char_class: dict, char: str) -> bool:
    """Check if a character matches a character class."""
    negated = char_class['negated']
    members = char_class['members']

    matched = False
    for member in members:
        if member['type'] == 'literal':
            if char == member['char']:
                matched = True
                break
        elif member['type'] == 'range':
            if ord(member['start']) <= ord(char) <= ord(member['end']):
                matched = True
                break

    if negated:
        return not matched
    else:
        return matched
